import React, { useState, useEffect } from 'react';
import { Menu, X, Waves } from 'lucide-react';
import { NAV_LINKS, BRAND } from '../constants';

const Header: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${scrolled ? 'bg-white shadow-lg py-3' : 'bg-transparent py-5'}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="bg-brand-dark p-2 rounded-lg">
              <Waves className="w-6 h-6 text-brand-light" />
            </div>
            <span className={`text-xl font-display font-bold ${scrolled ? 'text-brand-dark' : 'text-white'}`}>
              Blackshack
            </span>
          </div>

          {/* Desktop Nav */}
          <div className="hidden md:flex items-center space-x-8">
            {NAV_LINKS.map((link) => (
              <a
                key={link.href}
                href={link.href}
                className={`font-semibold hover:text-brand-teal transition-colors ${scrolled ? 'text-gray-700' : 'text-white'}`}
              >
                {link.label}
              </a>
            ))}
            <a
              href="#booking"
              className="bg-brand-light text-brand-dark px-6 py-2 rounded-full font-bold hover:bg-brand-teal transition-all shadow-md"
            >
              Reservar Clase
            </a>
          </div>

          {/* Mobile Menu Toggle */}
          <div className="md:hidden">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className={scrolled ? 'text-brand-dark' : 'text-white'}
            >
              {isOpen ? <X size={28} /> : <Menu size={28} />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      <div className={`md:hidden absolute w-full bg-white shadow-xl transition-all duration-300 ${isOpen ? 'top-full opacity-100' : '-top-[500px] opacity-0'}`}>
        <div className="px-4 py-6 space-y-4">
          {NAV_LINKS.map((link) => (
            <a
              key={link.href}
              href={link.href}
              className="block text-lg font-semibold text-gray-800 hover:text-brand-accent"
              onClick={() => setIsOpen(false)}
            >
              {link.label}
            </a>
          ))}
          <a
            href="#booking"
            className="block w-full bg-brand-dark text-white text-center py-3 rounded-lg font-bold"
            onClick={() => setIsOpen(false)}
          >
