import React, { useState, useRef } from 'react';
import { Send, User, Waves, AlignLeft } from 'lucide-react';
import { BRAND } from '../constants';

const BookingForm: React.FC = () => {
  const [status, setStatus] = useState<'idle' | 'success'>('idle');
  const formRef = useRef<HTMLFormElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!formRef.current) return;

    const formData = new FormData(formRef.current);
    const nombre = formData.get('nombre') as string;
    const nivel = formData.get('nivel') as string;
    const detalles = formData.get('detalles') as string;

    // Estructurar el mensaje de forma ordenada
    const mensaje = `Hola *${BRAND.name}*! 👋 Me gustaría reservar una sesión de surf.%0A%0A` +
                   `👤 *Nombre:* ${nombre}%0A` +
                   `🌊 *Nivel:* ${nivel}%0A` +
                   `📝 *Detalles:* ${detalles}`;

    // Abrir WhatsApp en una nueva pestaña
    const whatsappUrl = `${BRAND.whatsapp}?text=${mensaje}`;
    window.open(whatsappUrl, '_blank');

    setStatus('success');
  };

  if (status === 'success') {
    return (
      <div id="booking" className="max-w-2xl mx-auto bg-white border border-gray-100 p-12 md:p-20 text-center shadow-2xl animate-in fade-in zoom-in duration-500">
        <div className="w-20 h-20 bg-brand-light/30 text-brand-teal rounded-full flex items-center justify-center mx-auto mb-8">
          <Send size={32} />
        </div>
        <h3 className="text-4xl font-display font-bold text-brand-dark mb-6 tracking-tight">¡Enviando!</h3>
        <p className="text-gray-500 text-lg font-light mb-12">Se ha abierto una ventana de WhatsApp con tu información. Por favor, dale a "Enviar" en WhatsApp para terminar de contactarnos.</p>
        <button 
          onClick={() => setStatus('idle')}
          className="bg-brand-dark text-white px-12 py-4 hover:bg-brand-accent transition-all uppercase text-[10px] font-black tracking-[0.3em]"
        >
          Volver
        </button>
      </div>
    );
  }

  return (
    <div id="booking" className="max-w-3xl mx-auto bg-white border border-gray-100 shadow-2xl relative overflow-hidden p-8 md:p-16">
      {/* Background Decor */}
      <div className="absolute top-0 right-0 w-32 h-32 bg-brand-light/10 rounded-full -mr-16 -mt-16 blur-2xl"></div>

      <div className="relative z-10 text-center mb-12">
        <h4 className="text-brand-accent font-bold uppercase tracking-[0.4em] text-[10px] mb-4">Reserva tu sesión</h4>
        <h2 className="text-4xl md:text-5xl font-display font-bold text-brand-dark tracking-tighter">
          ¿Surfeamos <span className="italic font-light">hoy?</span>
        </h2>
      </div>

      <form ref={formRef} onSubmit={handleSubmit} className="space-y-10 relative z-10">
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400 flex items-center gap-2">
            <User size={14} className="text-brand-teal" /> Nombre
          </label>
          <input
            name="nombre"
            required
            type="text"
            placeholder="Escribe tu nombre"
            className="w-full bg-transparent border-b border-gray-200 py-3 focus:border-brand-dark outline-none transition-all font-light text-lg placeholder:text-gray-200"
          />
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400 flex items-center gap-2">
            <Waves size={14} className="text-brand-teal" /> Nivel
          </label>
          <select 
            name="nivel"
            className="w-full bg-transparent border-b border-gray-200 py-3 focus:border-brand-dark outline-none transition-all font-light text-lg appearance-none cursor-pointer"
          >
            <option value="Principiante">Principiante</option>
            <option value="Intermedio">Intermedio</option>
            <option value="Avanzado">Avanzado</option>
          </select>
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400 flex items-center gap-2">
            <AlignLeft size={14} className="text-brand-teal" /> Detalles breves
          </label>
          <textarea
            name="detalles"
            required
            rows={2}
            placeholder="Cuéntanos cuántos son y cómo contactarte..."
            className="w-full bg-transparent border-b border-gray-200 py-3 focus:border-brand-dark outline-none transition-all font-light text-lg placeholder:text-gray-200 resize-none h-24"
          ></textarea>
        </div>

        <button
          type="submit"
          className="w-full bg-brand-dark text-white py-6 group flex items-center justify-center gap-4 hover:bg-brand-accent transition-all uppercase text-[11px] font-black tracking-[0.5em] shadow-lg active:scale-[0.98]"
        >
          ENVIAR RESERVA A WHATSAPP
          <Send size={16} className="group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
        </button>
      </form>
    </div>
  );
