const App: React.FC = () => {
  // Manejador de navegación interna ultra-robusto
  useEffect(() => {
    const handleInternalNavigation = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      const anchor = target.closest('a');

      if (!anchor) return;

      const href = anchor.getAttribute('href');

      // Solo interceptamos enlaces que comienzan con # (anclas internas)
      if (href && href.startsWith('#')) {
        e.preventDefault();

        // Si el href es solo "#", scrolleamos al inicio
        if (href === '#') {
          window.scrollTo({ top: 0, behavior: 'smooth' });
          window.history.pushState(null, '', window.location.pathname);
          return;
        }

        const targetId = href.substring(1);
        const targetElement = document.getElementById(targetId);

        if (targetElement) {
          const headerOffset = 90; // Ajuste para el header fijo
          const elementPosition = targetElement.getBoundingClientRect().top;
          const offsetPosition = elementPosition + window.pageYOffset - headerOffset;

          window.scrollTo({
            top: offsetPosition,
            behavior: 'smooth'
          });

          // Actualizamos la URL sin disparar recargas o eventos de navegación del navegador
          window.history.pushState(null, '', href);
        }
      }
    };

    document.addEventListener('click', handleInternalNavigation);
    return () => document.removeEventListener('click', handleInternalNavigation);
  }, []);

  return (
    <div className="min-h-screen bg-white">
      <Header />

      <main>
        <Hero />

